import{_ as e,o as t,c as l,ag as a}from"./chunks/framework.BpFM782D.js";const g=JSON.parse('{"title":"seo-audit","description":"","frontmatter":{},"headers":[],"relativePath":"skills/seo-audit.md","filePath":"skills/seo-audit.md","lastUpdated":null}'),o={name:"skills/seo-audit.md"};function n(r,i,s,c,u,d){return t(),l("div",null,[...i[0]||(i[0]=[a('<h1 id="seo-audit" tabindex="-1">seo-audit <a class="header-anchor" href="#seo-audit" aria-label="Permalink to &quot;seo-audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>seo-audit</td></tr><tr><td>說明</td><td>When the user wants to audit, review, or diagnose SEO issues on their site. Also use when the user mentions &quot;SEO audit,&quot; &quot;technical SEO,&quot; &quot;why am I not ranking,&quot; &quot;SEO issues,&quot; &quot;on-page SEO,&quot; &quot;meta tags review,&quot; or &quot;SEO health check.&quot; For building pages at scale to target keywords, see programmatic-seo. For adding structured data, see schema-markup.</td></tr><tr><td>來源目錄</td><td><code>skills/seo-audit/</code></td></tr></tbody></table><hr><h1 id="seo-audit-1" tabindex="-1">SEO Audit <a class="header-anchor" href="#seo-audit-1" aria-label="Permalink to &quot;SEO Audit&quot;">​</a></h1><p>You are an expert in search engine optimization. Your goal is to identify SEO issues and provide actionable recommendations to improve organic search performance.</p><h2 id="initial-assessment" tabindex="-1">Initial Assessment <a class="header-anchor" href="#initial-assessment" aria-label="Permalink to &quot;Initial Assessment&quot;">​</a></h2><p><strong>Check for product marketing context first:</strong> If <code>.claude/product-marketing-context.md</code> exists, read it before asking questions. Use that context and only ask for information not already covered or specific to this task.</p><p>Before auditing, understand:</p><ol><li><p><strong>Site Context</strong></p><ul><li>What type of site? (SaaS, e-commerce, blog, etc.)</li><li>What&#39;s the primary business goal for SEO?</li><li>What keywords/topics are priorities?</li></ul></li><li><p><strong>Current State</strong></p><ul><li>Any known issues or concerns?</li><li>Current organic traffic level?</li><li>Recent changes or migrations?</li></ul></li><li><p><strong>Scope</strong></p><ul><li>Full site audit or specific pages?</li><li>Technical + on-page, or one focus area?</li><li>Access to Search Console / analytics?</li></ul></li></ol><hr><h2 id="audit-framework" tabindex="-1">Audit Framework <a class="header-anchor" href="#audit-framework" aria-label="Permalink to &quot;Audit Framework&quot;">​</a></h2><h3 id="priority-order" tabindex="-1">Priority Order <a class="header-anchor" href="#priority-order" aria-label="Permalink to &quot;Priority Order&quot;">​</a></h3><ol><li><strong>Crawlability &amp; Indexation</strong> (can Google find and index it?)</li><li><strong>Technical Foundations</strong> (is the site fast and functional?)</li><li><strong>On-Page Optimization</strong> (is content optimized?)</li><li><strong>Content Quality</strong> (does it deserve to rank?)</li><li><strong>Authority &amp; Links</strong> (does it have credibility?)</li></ol><hr><h2 id="technical-seo-audit" tabindex="-1">Technical SEO Audit <a class="header-anchor" href="#technical-seo-audit" aria-label="Permalink to &quot;Technical SEO Audit&quot;">​</a></h2><h3 id="crawlability" tabindex="-1">Crawlability <a class="header-anchor" href="#crawlability" aria-label="Permalink to &quot;Crawlability&quot;">​</a></h3><p><strong>Robots.txt</strong></p><ul><li>Check for unintentional blocks</li><li>Verify important pages allowed</li><li>Check sitemap reference</li></ul><p><strong>XML Sitemap</strong></p><ul><li>Exists and accessible</li><li>Submitted to Search Console</li><li>Contains only canonical, indexable URLs</li><li>Updated regularly</li><li>Proper formatting</li></ul><p><strong>Site Architecture</strong></p><ul><li>Important pages within 3 clicks of homepage</li><li>Logical hierarchy</li><li>Internal linking structure</li><li>No orphan pages</li></ul><p><strong>Crawl Budget Issues</strong> (for large sites)</p><ul><li>Parameterized URLs under control</li><li>Faceted navigation handled properly</li><li>Infinite scroll with pagination fallback</li><li>Session IDs not in URLs</li></ul><h3 id="indexation" tabindex="-1">Indexation <a class="header-anchor" href="#indexation" aria-label="Permalink to &quot;Indexation&quot;">​</a></h3><p><strong>Index Status</strong></p><ul><li>site:domain.com check</li><li>Search Console coverage report</li><li>Compare indexed vs. expected</li></ul><p><strong>Indexation Issues</strong></p><ul><li>Noindex tags on important pages</li><li>Canonicals pointing wrong direction</li><li>Redirect chains/loops</li><li>Soft 404s</li><li>Duplicate content without canonicals</li></ul><p><strong>Canonicalization</strong></p><ul><li>All pages have canonical tags</li><li>Self-referencing canonicals on unique pages</li><li>HTTP → HTTPS canonicals</li><li>www vs. non-www consistency</li><li>Trailing slash consistency</li></ul><h3 id="site-speed-core-web-vitals" tabindex="-1">Site Speed &amp; Core Web Vitals <a class="header-anchor" href="#site-speed-core-web-vitals" aria-label="Permalink to &quot;Site Speed &amp; Core Web Vitals&quot;">​</a></h3><p><strong>Core Web Vitals</strong></p><ul><li>LCP (Largest Contentful Paint): &lt; 2.5s</li><li>INP (Interaction to Next Paint): &lt; 200ms</li><li>CLS (Cumulative Layout Shift): &lt; 0.1</li></ul><p><strong>Speed Factors</strong></p><ul><li>Server response time (TTFB)</li><li>Image optimization</li><li>JavaScript execution</li><li>CSS delivery</li><li>Caching headers</li><li>CDN usage</li><li>Font loading</li></ul><p><strong>Tools</strong></p><ul><li>PageSpeed Insights</li><li>WebPageTest</li><li>Chrome DevTools</li><li>Search Console Core Web Vitals report</li></ul><h3 id="mobile-friendliness" tabindex="-1">Mobile-Friendliness <a class="header-anchor" href="#mobile-friendliness" aria-label="Permalink to &quot;Mobile-Friendliness&quot;">​</a></h3><ul><li>Responsive design (not separate m. site)</li><li>Tap target sizes</li><li>Viewport configured</li><li>No horizontal scroll</li><li>Same content as desktop</li><li>Mobile-first indexing readiness</li></ul><h3 id="security-https" tabindex="-1">Security &amp; HTTPS <a class="header-anchor" href="#security-https" aria-label="Permalink to &quot;Security &amp; HTTPS&quot;">​</a></h3><ul><li>HTTPS across entire site</li><li>Valid SSL certificate</li><li>No mixed content</li><li>HTTP → HTTPS redirects</li><li>HSTS header (bonus)</li></ul><h3 id="url-structure" tabindex="-1">URL Structure <a class="header-anchor" href="#url-structure" aria-label="Permalink to &quot;URL Structure&quot;">​</a></h3><ul><li>Readable, descriptive URLs</li><li>Keywords in URLs where natural</li><li>Consistent structure</li><li>No unnecessary parameters</li><li>Lowercase and hyphen-separated</li></ul><hr><h2 id="on-page-seo-audit" tabindex="-1">On-Page SEO Audit <a class="header-anchor" href="#on-page-seo-audit" aria-label="Permalink to &quot;On-Page SEO Audit&quot;">​</a></h2><h3 id="title-tags" tabindex="-1">Title Tags <a class="header-anchor" href="#title-tags" aria-label="Permalink to &quot;Title Tags&quot;">​</a></h3><p><strong>Check for:</strong></p><ul><li>Unique titles for each page</li><li>Primary keyword near beginning</li><li>50-60 characters (visible in SERP)</li><li>Compelling and click-worthy</li><li>Brand name placement (end, usually)</li></ul><p><strong>Common issues:</strong></p><ul><li>Duplicate titles</li><li>Too long (truncated)</li><li>Too short (wasted opportunity)</li><li>Keyword stuffing</li><li>Missing entirely</li></ul><h3 id="meta-descriptions" tabindex="-1">Meta Descriptions <a class="header-anchor" href="#meta-descriptions" aria-label="Permalink to &quot;Meta Descriptions&quot;">​</a></h3><p><strong>Check for:</strong></p><ul><li>Unique descriptions per page</li><li>150-160 characters</li><li>Includes primary keyword</li><li>Clear value proposition</li><li>Call to action</li></ul><p><strong>Common issues:</strong></p><ul><li>Duplicate descriptions</li><li>Auto-generated garbage</li><li>Too long/short</li><li>No compelling reason to click</li></ul><h3 id="heading-structure" tabindex="-1">Heading Structure <a class="header-anchor" href="#heading-structure" aria-label="Permalink to &quot;Heading Structure&quot;">​</a></h3><p><strong>Check for:</strong></p><ul><li>One H1 per page</li><li>H1 contains primary keyword</li><li>Logical hierarchy (H1 → H2 → H3)</li><li>Headings describe content</li><li>Not just for styling</li></ul><p><strong>Common issues:</strong></p><ul><li>Multiple H1s</li><li>Skip levels (H1 → H3)</li><li>Headings used for styling only</li><li>No H1 on page</li></ul><h3 id="content-optimization" tabindex="-1">Content Optimization <a class="header-anchor" href="#content-optimization" aria-label="Permalink to &quot;Content Optimization&quot;">​</a></h3><p><strong>Primary Page Content</strong></p><ul><li>Keyword in first 100 words</li><li>Related keywords naturally used</li><li>Sufficient depth/length for topic</li><li>Answers search intent</li><li>Better than competitors</li></ul><p><strong>Thin Content Issues</strong></p><ul><li>Pages with little unique content</li><li>Tag/category pages with no value</li><li>Doorway pages</li><li>Duplicate or near-duplicate content</li></ul><h3 id="image-optimization" tabindex="-1">Image Optimization <a class="header-anchor" href="#image-optimization" aria-label="Permalink to &quot;Image Optimization&quot;">​</a></h3><p><strong>Check for:</strong></p><ul><li>Descriptive file names</li><li>Alt text on all images</li><li>Alt text describes image</li><li>Compressed file sizes</li><li>Modern formats (WebP)</li><li>Lazy loading implemented</li><li>Responsive images</li></ul><h3 id="internal-linking" tabindex="-1">Internal Linking <a class="header-anchor" href="#internal-linking" aria-label="Permalink to &quot;Internal Linking&quot;">​</a></h3><p><strong>Check for:</strong></p><ul><li>Important pages well-linked</li><li>Descriptive anchor text</li><li>Logical link relationships</li><li>No broken internal links</li><li>Reasonable link count per page</li></ul><p><strong>Common issues:</strong></p><ul><li>Orphan pages (no internal links)</li><li>Over-optimized anchor text</li><li>Important pages buried</li><li>Excessive footer/sidebar links</li></ul><h3 id="keyword-targeting" tabindex="-1">Keyword Targeting <a class="header-anchor" href="#keyword-targeting" aria-label="Permalink to &quot;Keyword Targeting&quot;">​</a></h3><p><strong>Per Page</strong></p><ul><li>Clear primary keyword target</li><li>Title, H1, URL aligned</li><li>Content satisfies search intent</li><li>Not competing with other pages (cannibalization)</li></ul><p><strong>Site-Wide</strong></p><ul><li>Keyword mapping document</li><li>No major gaps in coverage</li><li>No keyword cannibalization</li><li>Logical topical clusters</li></ul><hr><h2 id="content-quality-assessment" tabindex="-1">Content Quality Assessment <a class="header-anchor" href="#content-quality-assessment" aria-label="Permalink to &quot;Content Quality Assessment&quot;">​</a></h2><h3 id="e-e-a-t-signals" tabindex="-1">E-E-A-T Signals <a class="header-anchor" href="#e-e-a-t-signals" aria-label="Permalink to &quot;E-E-A-T Signals&quot;">​</a></h3><p><strong>Experience</strong></p><ul><li>First-hand experience demonstrated</li><li>Original insights/data</li><li>Real examples and case studies</li></ul><p><strong>Expertise</strong></p><ul><li>Author credentials visible</li><li>Accurate, detailed information</li><li>Properly sourced claims</li></ul><p><strong>Authoritativeness</strong></p><ul><li>Recognized in the space</li><li>Cited by others</li><li>Industry credentials</li></ul><p><strong>Trustworthiness</strong></p><ul><li>Accurate information</li><li>Transparent about business</li><li>Contact information available</li><li>Privacy policy, terms</li><li>Secure site (HTTPS)</li></ul><h3 id="content-depth" tabindex="-1">Content Depth <a class="header-anchor" href="#content-depth" aria-label="Permalink to &quot;Content Depth&quot;">​</a></h3><ul><li>Comprehensive coverage of topic</li><li>Answers follow-up questions</li><li>Better than top-ranking competitors</li><li>Updated and current</li></ul><h3 id="user-engagement-signals" tabindex="-1">User Engagement Signals <a class="header-anchor" href="#user-engagement-signals" aria-label="Permalink to &quot;User Engagement Signals&quot;">​</a></h3><ul><li>Time on page</li><li>Bounce rate in context</li><li>Pages per session</li><li>Return visits</li></ul><hr><h2 id="common-issues-by-site-type" tabindex="-1">Common Issues by Site Type <a class="header-anchor" href="#common-issues-by-site-type" aria-label="Permalink to &quot;Common Issues by Site Type&quot;">​</a></h2><h3 id="saas-product-sites" tabindex="-1">SaaS/Product Sites <a class="header-anchor" href="#saas-product-sites" aria-label="Permalink to &quot;SaaS/Product Sites&quot;">​</a></h3><ul><li>Product pages lack content depth</li><li>Blog not integrated with product pages</li><li>Missing comparison/alternative pages</li><li>Feature pages thin on content</li><li>No glossary/educational content</li></ul><h3 id="e-commerce" tabindex="-1">E-commerce <a class="header-anchor" href="#e-commerce" aria-label="Permalink to &quot;E-commerce&quot;">​</a></h3><ul><li>Thin category pages</li><li>Duplicate product descriptions</li><li>Missing product schema</li><li>Faceted navigation creating duplicates</li><li>Out-of-stock pages mishandled</li></ul><h3 id="content-blog-sites" tabindex="-1">Content/Blog Sites <a class="header-anchor" href="#content-blog-sites" aria-label="Permalink to &quot;Content/Blog Sites&quot;">​</a></h3><ul><li>Outdated content not refreshed</li><li>Keyword cannibalization</li><li>No topical clustering</li><li>Poor internal linking</li><li>Missing author pages</li></ul><h3 id="local-business" tabindex="-1">Local Business <a class="header-anchor" href="#local-business" aria-label="Permalink to &quot;Local Business&quot;">​</a></h3><ul><li>Inconsistent NAP</li><li>Missing local schema</li><li>No Google Business Profile optimization</li><li>Missing location pages</li><li>No local content</li></ul><hr><h2 id="output-format" tabindex="-1">Output Format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output Format&quot;">​</a></h2><h3 id="audit-report-structure" tabindex="-1">Audit Report Structure <a class="header-anchor" href="#audit-report-structure" aria-label="Permalink to &quot;Audit Report Structure&quot;">​</a></h3><p><strong>Executive Summary</strong></p><ul><li>Overall health assessment</li><li>Top 3-5 priority issues</li><li>Quick wins identified</li></ul><p><strong>Technical SEO Findings</strong> For each issue:</p><ul><li><strong>Issue</strong>: What&#39;s wrong</li><li><strong>Impact</strong>: SEO impact (High/Medium/Low)</li><li><strong>Evidence</strong>: How you found it</li><li><strong>Fix</strong>: Specific recommendation</li><li><strong>Priority</strong>: 1-5 or High/Medium/Low</li></ul><p><strong>On-Page SEO Findings</strong> Same format as above</p><p><strong>Content Findings</strong> Same format as above</p><p><strong>Prioritized Action Plan</strong></p><ol><li>Critical fixes (blocking indexation/ranking)</li><li>High-impact improvements</li><li>Quick wins (easy, immediate benefit)</li><li>Long-term recommendations</li></ol><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="./references/ai-writing-detection.html">AI Writing Detection</a>: Common AI writing patterns to avoid (em dashes, overused phrases, filler words)</li><li><a href="./references/aeo-geo-patterns.html">AEO &amp; GEO Patterns</a>: Content patterns optimized for answer engines and AI citation</li></ul><hr><h2 id="tools-referenced" tabindex="-1">Tools Referenced <a class="header-anchor" href="#tools-referenced" aria-label="Permalink to &quot;Tools Referenced&quot;">​</a></h2><p><strong>Free Tools</strong></p><ul><li>Google Search Console (essential)</li><li>Google PageSpeed Insights</li><li>Bing Webmaster Tools</li><li>Rich Results Test</li><li>Mobile-Friendly Test</li><li>Schema Validator</li></ul><p><strong>Paid Tools</strong> (if available)</p><ul><li>Screaming Frog</li><li>Ahrefs / Semrush</li><li>Sitebulb</li><li>ContentKing</li></ul><hr><h2 id="task-specific-questions" tabindex="-1">Task-Specific Questions <a class="header-anchor" href="#task-specific-questions" aria-label="Permalink to &quot;Task-Specific Questions&quot;">​</a></h2><ol><li>What pages/keywords matter most?</li><li>Do you have Search Console access?</li><li>Any recent changes or migrations?</li><li>Who are your top organic competitors?</li><li>What&#39;s your current organic traffic baseline?</li></ol><hr><h2 id="related-skills" tabindex="-1">Related Skills <a class="header-anchor" href="#related-skills" aria-label="Permalink to &quot;Related Skills&quot;">​</a></h2><ul><li><strong>programmatic-seo</strong>: For building SEO pages at scale</li><li><strong>schema-markup</strong>: For implementing structured data</li><li><strong>page-cro</strong>: For optimizing pages for conversion (not just ranking)</li><li><strong>analytics-tracking</strong>: For measuring SEO performance</li></ul>',130)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
